import dlartg = require( './index' );


// TESTS //

// The function returns void...
{
	const F = new Float64Array( 1 );
	const G = new Float64Array( 1 );
	const CS = new Float64Array( 1 );
	const SN = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg( F, G, CS, SN, R ); // $ExpectType void
}

// The compiler throws an error if the function is provided a first argument which is not a Float64Array...
{
	const G = new Float64Array( 1 );
	const CS = new Float64Array( 1 );
	const SN = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg( '5', G, CS, SN, R ); // $ExpectError
	dlartg( 5, G, CS, SN, R ); // $ExpectError
	dlartg( true, G, CS, SN, R ); // $ExpectError
	dlartg( false, G, CS, SN, R ); // $ExpectError
	dlartg( null, G, CS, SN, R ); // $ExpectError
	dlartg( void 0, G, CS, SN, R ); // $ExpectError
	dlartg( [], G, CS, SN, R ); // $ExpectError
	dlartg( {}, G, CS, SN, R ); // $ExpectError
	dlartg( ( x: number ): number => x, G, CS, SN, R ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Float64Array...
{
	const F = new Float64Array( 1 );
	const CS = new Float64Array( 1 );
	const SN = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg( F, '5', CS, SN, R ); // $ExpectError
	dlartg( F, 5, CS, SN, R ); // $ExpectError
	dlartg( F, true, CS, SN, R ); // $ExpectError
	dlartg( F, false, CS, SN, R ); // $ExpectError
	dlartg( F, null, CS, SN, R ); // $ExpectError
	dlartg( F, void 0, CS, SN, R ); // $ExpectError
	dlartg( F, [], CS, SN, R ); // $ExpectError
	dlartg( F, {}, CS, SN, R ); // $ExpectError
	dlartg( F, ( x: number ): number => x, CS, SN, R ); // $ExpectError
}

